/** Every catalogued behavior's `client.js`, in catalog order. */
export const MODULE_CLIENT_JS = "/* behavior: contact-form */\n{\n/**\n * Vetted client behaviour for the `contact-form` behavior (REQ-85).\n *\n * The server-rendered form works with no JavaScript: a real `<form\n * method=\"post\" action=…>` submits by reloading against the endpoint. This\n * upgrades that baseline — when JS runs, the submit is intercepted and sent as a\n * JSON `fetch`, keeping the visitor on the page and swapping in the success\n * message inline.\n *\n * Authored as self-contained browser JavaScript (no imports) so the render\n * pipeline ships it verbatim in `capabilities.js`; unit-tested by importing this\n * module against a JSDOM + mocked `fetch`. **Isolation** (REQ-85): defensive\n * throughout, so a failure degrades to the no-JS post baseline.\n */\n\nconst ROOT_SELECTOR = '[data-contact-form-root]'\nconst ERROR_SELECTOR = '[data-contact-error]'\nconst SUCCESS_SELECTOR = '[data-contact-success]'\n\nfunction showError(form, message) {\n  const errorEl = form.querySelector(ERROR_SELECTOR)\n  if (errorEl) {\n    errorEl.textContent = message\n    errorEl.hidden = false\n  }\n}\n\n/**\n * BUG-28 — whether this submission can be enhanced at all.\n *\n * `assertSafeUrl` accepts `mailto:` and `tel:` actions, but `fetch()` cannot send\n * to either: it rejects, and the catch below reports \"could not reach the server\"\n * on a form that would have worked perfectly by native submit. Worse, the\n * `preventDefault()` had already cancelled that native submit — so the vetted\n * no-JS baseline this file documents as its degradation path was unreachable for\n * exactly the actions that needed it.\n *\n * The scheme already carries the answer, so no config field is added for it\n * (DOC-25 §2 — a dial for something the data determines is the wrong shape).\n * http(s), relative, and empty (post-to-self) enhance; anything else, including\n * anything unparseable, falls through to the browser.\n */\nfunction canEnhance(action) {\n  try {\n    const scheme = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(String(action).trim())\n    return !scheme || /^https?$/i.test(scheme[1])\n  } catch (_e) {\n    return false\n  }\n}\n\nasync function handleSubmit(form, event) {\n  // Decided BEFORE preventDefault, so a non-fetchable action keeps its native submit.\n  if (!canEnhance(form.getAttribute('action') || '')) return\n  event.preventDefault()\n\n  const errorEl = form.querySelector(ERROR_SELECTOR)\n  if (errorEl) {\n    errorEl.hidden = true\n    errorEl.textContent = ''\n  }\n\n  // Serialise the form's named controls to a flat JSON object — the honeypot\n  // field rides along so the server can reject filled-honeypot submissions.\n  const payload = {}\n  for (const [name, value] of new FormData(form).entries()) {\n    payload[name] = typeof value === 'string' ? value : value.name\n  }\n\n  const action = form.getAttribute('action') || ''\n\n  let response\n  try {\n    response = await fetch(action, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(payload),\n    })\n  } catch (_e) {\n    showError(form, 'Could not reach the server. Please try again.')\n    return\n  }\n\n  if (response.ok) {\n    const root = form.closest(ROOT_SELECTOR)\n    const success = root ? root.querySelector(SUCCESS_SELECTOR) : null\n    const successHtml =\n      success && 'content' in success ? success.innerHTML : success ? success.innerHTML : ''\n    if (root) {\n      root.innerHTML = successHtml || '<p>Thanks — your message has been sent.</p>'\n    }\n    return\n  }\n\n  // Non-2xx: surface the server's error inline without navigating away.\n  let message = `Something went wrong (${response.status}). Please try again.`\n  try {\n    const body = await response.json()\n    if (body && typeof body.error === 'string' && body.error) {\n      message = body.error\n    }\n  } catch (_e) {\n    // Non-JSON error body — keep the status-based default message.\n  }\n  showError(form, message)\n}\n\n/** Attach the JSON-submit enhancement to a single contact form. */\nfunction enhanceContactForm(form) {\n  form.addEventListener('submit', function (event) {\n    void handleSubmit(form, event)\n  })\n}\n\n/** Enhance every contact form in `root` (defaults to `document`). */\nfunction enhanceAllContactForms(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const forms = scope.querySelectorAll('form[data-contact-form]')\n  for (let i = 0; i < forms.length; i++) enhanceContactForm(forms[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllContactForms()\n    })\n  } else {\n    enhanceAllContactForms()\n  }\n}\n}\n\n/* behavior: carousel */\n{\n/**\n * Vetted client behaviour for the `carousel` behavior (REQ-85).\n *\n * A behavior module ships fixed, tested behavioural CODE — this is the\n * carousel's. It is authored as self-contained browser JavaScript (no imports)\n * so the render pipeline can ship it verbatim as a static `capabilities.js`\n * asset; the pure algorithm is unit-tested by importing this module directly.\n *\n * Behaviour: the SSR baseline is a pure CSS `scroll-snap` track (usable with no\n * JS). This upgrades it — `data-carousel-autoplay` advances the track on a timer,\n * `data-carousel-loop` wraps from the last slide back to the first.\n *\n * **Isolation** (REQ-85): every entry point is defensive — a missing element, a\n * one-slide track, or an absent timer API degrades to the static baseline and\n * never throws, so a misbehaving carousel can never break page robustness.\n */\n\nconst AUTOPLAY_INTERVAL_MS = 5000\n\n/** Advance a track by one slide, wrapping to the start when `loop` and at the end. */\nfunction advanceTrack(track, loop) {\n  const slide = track.querySelector('.carousel__slide')\n  const step = slide ? slide.getBoundingClientRect().width : track.clientWidth\n  const atEnd = track.scrollLeft + track.clientWidth >= track.scrollWidth - 1\n  if (atEnd) {\n    if (loop) track.scrollTo({ left: 0, behavior: 'smooth' })\n    return\n  }\n  track.scrollBy({ left: step, behavior: 'smooth' })\n}\n\n/**\n * REQ-96 — mark the dot matching the slide nearest the track's scroll position.\n *\n * Which slide is current is a *behavioural state*, so the module owns it: a dot's\n * look is an L1 subtree, and a static subtree has no state axis to say \"this one\"\n * with. The module marks it and gives it the one invariant opacity rule; L1 keeps\n * everything else.\n */\nfunction syncDots(section, track) {\n  const dots = section.querySelectorAll('[data-carousel-dot]')\n  if (dots.length === 0) return\n  const slides = track.querySelectorAll('.carousel__slide')\n  let current = 0\n  let best = Infinity\n  for (let i = 0; i < slides.length; i++) {\n    const distance = Math.abs(slides[i].offsetLeft - track.scrollLeft)\n    if (distance < best) {\n      best = distance\n      current = i\n    }\n  }\n  for (let i = 0; i < dots.length; i++) {\n    if (i === current) dots[i].setAttribute('data-carousel-current', '')\n    else dots[i].removeAttribute('data-carousel-current')\n  }\n}\n\n/**\n * Attach the dot indicator and autoplay/loop to one carousel `<section>`.\n * `schedule` is injectable so the behaviour is unit-testable without a real\n * timer; it defaults to the global `setInterval`.\n */\nfunction enhanceCarousel(section, schedule) {\n  try {\n    // The indicator is independent of autoplay, and its own failure must not cost\n    // the track its autoplay — hence its own guard rather than the outer one.\n    try {\n      const dotTrack = section.querySelector('.carousel__track')\n      if (dotTrack && typeof dotTrack.addEventListener === 'function') {\n        dotTrack.addEventListener('scroll', function () {\n          try {\n            syncDots(section, dotTrack)\n          } catch (_e) {\n            // A failed indicator update must never break scrolling.\n          }\n        })\n      }\n    } catch (_e) {\n      // No indicator; the track still scrolls and still autoplays.\n    }\n    if (!section.hasAttribute('data-carousel-autoplay')) return\n    const loop = section.hasAttribute('data-carousel-loop')\n    const track = section.querySelector('.carousel__track')\n    if (!track || track.querySelectorAll('.carousel__slide').length < 2) return\n    const timer = schedule || (typeof setInterval === 'function' ? setInterval : null)\n    if (!timer) return\n    timer(function () {\n      try {\n        advanceTrack(track, loop)\n      } catch (_e) {\n        // A single failed advance must never break the page.\n      }\n    }, AUTOPLAY_INTERVAL_MS)\n  } catch (_e) {\n    // Isolation: enhancement failure degrades to the no-JS baseline.\n  }\n}\n\n/** Enhance every carousel in `root` (defaults to `document`). */\nfunction enhanceAllCarousels(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const sections = scope.querySelectorAll('[data-carousel]')\n  for (let i = 0; i < sections.length; i++) enhanceCarousel(sections[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less test imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllCarousels()\n    })\n  } else {\n    enhanceAllCarousels()\n  }\n}\n}\n\n/* behavior: account-portal */\n{\n/**\n * Vetted client behaviour for the `account-portal` behavior ([[REQ-183]]).\n *\n * TWO JOBS, AND NEITHER OF THEM DELETES ANYTHING. It fills the account line and\n * the holdings sentence from the endpoint the instance names, and it folds the\n * erasure explanation away behind the control. There is no third job: the only\n * request this file makes is a `GET`, and a UAT asserts that, because \"the button\n * does not delete the account\" has to be a property of the code rather than of a\n * promise ([[REQ-183]] §4.1).\n *\n * IT ONLY EVER SUBTRACTS. The server renders the explanation OPEN\n * (`component.ts` explains why), so every failure of this file — no script, a\n * throw, an endpoint that refuses — leaves a page that shows more of the truth\n * rather than a control that claims something the page cannot do ([[DOC-37]]\n * §6.2). That is why the collapse happens here and the reveal does not.\n *\n * Authored as self-contained browser JavaScript (no imports) so the render\n * pipeline ships it verbatim in `capabilities.js`; unit-tested by importing this\n * module against a JSDOM + mocked `fetch`. **Isolation** ([[DOC-25]]): defensive\n * throughout, so a failure degrades to the fully-expanded baseline.\n */\n\nconst PORTAL_SELECTOR = '[data-account-portal]'\nconst IDENTITY_SELECTOR = '[data-account-identity]'\nconst HOLDINGS_SELECTOR = '[data-account-holdings]'\nconst ERASURE_SELECTOR = '[data-account-erasure]'\nconst ERROR_SELECTOR = '[data-account-error]'\nconst REVEAL_SELECTOR = 'button[aria-expanded]'\n\n/**\n * How the person reading this portal is named on it.\n *\n * THE EMAIL IS THE FALLBACK AND NOT THE ORNAMENT. It is the identity the login\n * verified ([[DOC-40]] §2), so it is always true; a display name is a label\n * somebody set and may not exist. A blank line where a person's name goes reads\n * as a failure to load rather than as a name nobody has set — which is the same\n * reasoning the avatar surface already uses.\n *\n * IT IS THE PERSON AND NOT THE ACCOUNT ([[REQ-194]]). It was `accountLine`, over\n * a payload field called `account` that carried a person's display name and their\n * verified address — which is what the account looked like while it had no table.\n * The account is the payer and the owner of businesses; a portal's first line is\n * \"you are signed in as\", so it names the person and the noun says so.\n *\n * Pure and exported so both branches are provable without a DOM.\n */\nfunction identityLine(person) {\n  if (!person || typeof person !== 'object') return ''\n  const email = typeof person.email === 'string' ? person.email.trim() : ''\n  const name = typeof person.name === 'string' ? person.name.trim() : ''\n  if (name && email) return name + ' — ' + email\n  return name || email\n}\n\n/**\n * What erasure would take with it, in this account's own terms ([[REQ-183]] D6).\n *\n * THE SENTENCE IS COMPUTED, NOT AUTHORED, and that is the answer to the ticket's\n * third open question. \"Delete account\" is a request about the account, and an\n * account is relative to the business it is an account of ([[DOC-42]] §6) — so a\n * fixed sentence about businesses is wrong at one level or the other. This names\n * the businesses this account actually operates, and one level down, where an\n * account operates none, it returns nothing and the sentence does not appear.\n *\n * LAPSED BUSINESSES ARE INCLUDED. They are still the person's, they still hold\n * their site and their customers, and the population most likely to be reading\n * this page is exactly the one whose grants have lapsed. Omitting them would make\n * the surface understate what it destroys, on the one page where understating is\n * the failure ([[DOC-37]] §6.2).\n *\n * Pure and exported for the same reason as above.\n */\nfunction holdingsLine(businesses) {\n  const list = Array.isArray(businesses) ? businesses : []\n  const names = []\n  for (let i = 0; i < list.length; i++) {\n    const entry = list[i]\n    if (!entry || typeof entry !== 'object') continue\n    const name = typeof entry.name === 'string' && entry.name.trim() ? entry.name.trim() : entry.id\n    if (typeof name === 'string' && name) names.push(name)\n  }\n  if (names.length === 0) return ''\n  const noun = names.length === 1 ? 'business' : 'businesses'\n  return 'This account operates ' + names.length + ' ' + noun + ': ' + names.join(', ') + '.'\n}\n\n/** Show a node's text, or hide the node when there is nothing true to put in it. */\nfunction fill(node, text) {\n  if (!node) return\n  if (text) {\n    node.textContent = text\n    node.hidden = false\n  } else {\n    node.textContent = ''\n    node.hidden = true\n  }\n}\n\n/** Fold the explanation away, or open it, keeping the control's state honest. */\nfunction setDisclosure(section, open) {\n  try {\n    const erasure = section.querySelector(ERASURE_SELECTOR)\n    if (erasure) erasure.hidden = !open\n    const buttons = section.querySelectorAll(REVEAL_SELECTOR)\n    for (let i = 0; i < buttons.length; i++) {\n      buttons[i].setAttribute('aria-expanded', open ? 'true' : 'false')\n    }\n  } catch (_e) {\n    // A disclosure that cannot be moved stays where the server left it — open.\n  }\n}\n\n/** Read the caller's own account and write it into the two invariant elements. */\nasync function loadAccount(section, fetchImpl) {\n  const src = section.getAttribute('data-account-src')\n  if (!src) return\n  const call = fetchImpl || (typeof fetch === 'function' ? fetch : null)\n  if (!call) return\n\n  let payload\n  try {\n    // GET, credentials included — the endpoint authenticates by the origin's own\n    // session ([[DOC-40]] §3). No method, no body, nothing to send.\n    const response = await call(src, { method: 'GET', credentials: 'same-origin' })\n    if (!response || !response.ok) throw new Error('refused')\n    payload = await response.json()\n  } catch (_e) {\n    const error = section.querySelector(ERROR_SELECTOR)\n    if (error) error.hidden = false\n    return\n  }\n\n  if (!payload || typeof payload !== 'object') return\n  fill(section.querySelector(IDENTITY_SELECTOR), identityLine(payload.person))\n  fill(section.querySelector(HOLDINGS_SELECTOR), holdingsLine(payload.businesses))\n}\n\n/** Attach both behaviours to one portal `<section>`. */\nfunction enhanceAccountPortal(section, fetchImpl) {\n  try {\n    setDisclosure(section, false)\n    const buttons = section.querySelectorAll('button[aria-controls]')\n    for (let i = 0; i < buttons.length; i++) {\n      const button = buttons[i]\n      const opens = button.hasAttribute('aria-expanded')\n      button.addEventListener('click', function () {\n        setDisclosure(section, opens)\n      })\n    }\n    void loadAccount(section, fetchImpl)\n  } catch (_e) {\n    // Isolation: enhancement failure leaves the fully-expanded server baseline.\n  }\n}\n\n/** Enhance every portal in `root` (defaults to `document`). */\nfunction enhanceAllAccountPortals(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const sections = scope.querySelectorAll(PORTAL_SELECTOR)\n  for (let i = 0; i < sections.length; i++) enhanceAccountPortal(sections[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllAccountPortals()\n    })\n  } else {\n    enhanceAllAccountPortals()\n  }\n}\n}\n\n/* behavior: account-chrome */\n{\n/**\n * Vetted client behaviour for the `account-chrome` behavior ([[REQ-200]]).\n *\n * TWO JOBS, AND BOTH OF THEM ONLY SUBTRACT. It folds the sign-in form away\n * behind the Sign In control, and it upgrades the form's native POST to a\n * `fetch` so the visitor stays on the page. The server renders the form OPEN and\n * posting natively, so every failure of this file — no script, a throw, a blocked\n * bundle — leaves a page on which the address can still be sent.\n *\n * IT NEVER READS THE RESPONSE, AND THAT IS A REQUIREMENT RATHER THAN AN ECONOMY.\n * The issue endpoint must not reveal whether an address is known ([[REQ-134]]),\n * so the confirmation is shown when the request COMPLETES, at any status. A known\n * address and an unknown one are indistinguishable here by construction. Only a\n * request that never reached the server at all — a thrown `fetch` — shows the\n * error, because that is a fact about the network and not about the address.\n *\n * IT AUTHENTICATES NOTHING. There is no session read here and no state decided\n * here: which of the chrome's states is current is settled by the serving Worker\n * before the bytes leave it.\n *\n * Authored as self-contained browser JavaScript (no imports) so the render\n * pipeline ships it verbatim in `capabilities.js`; unit-tested by importing this\n * module against a JSDOM + mocked `fetch`. **Isolation** ([[DOC-25]]): defensive\n * throughout, so a failure degrades to the native-post baseline.\n */\n\nconst CHROME_SELECTOR = '[data-account-chrome]'\nconst DIALOG_SELECTOR = '[data-account-chrome-dialog]'\nconst SENT_SELECTOR = '[data-account-chrome-sent]'\nconst ERROR_SELECTOR = '[data-account-chrome-error]'\nconst OPEN_SELECTOR = '[data-account-chrome-open]'\nconst CLOSE_SELECTOR = '[data-account-chrome-close]'\nconst EMAIL_SELECTOR = '[data-account-chrome-email]'\n\n/** Open or fold away the sign-in form, keeping the control's state honest. */\nfunction setDialog(section, open) {\n  try {\n    const dialog = section.querySelector(DIALOG_SELECTOR)\n    if (dialog) dialog.hidden = !open\n    const openers = section.querySelectorAll(OPEN_SELECTOR)\n    for (let i = 0; i < openers.length; i++) {\n      openers[i].setAttribute('aria-expanded', open ? 'true' : 'false')\n    }\n    if (open) {\n      const email = section.querySelector(EMAIL_SELECTOR)\n      if (email && typeof email.focus === 'function') email.focus()\n    }\n  } catch (_e) {\n    // A dialog that cannot be moved stays where the server left it — open.\n  }\n}\n\n/**\n * Send the address and report the one message.\n *\n * Exported and given its `fetch` so the \"identical for a known and an unknown\n * address\" property is provable without a browser.\n */\nasync function submitAddress(section, form, fetchImpl) {\n  const sent = section.querySelector(SENT_SELECTOR)\n  const error = section.querySelector(ERROR_SELECTOR)\n  if (error) error.hidden = true\n\n  const action = form.getAttribute('action') || ''\n  const call = fetchImpl || (typeof fetch === 'function' ? fetch : null)\n  if (!call) return\n\n  const email = section.querySelector(EMAIL_SELECTOR)\n  const address = email && typeof email.value === 'string' ? email.value : ''\n\n  try {\n    await call(action, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      credentials: 'same-origin',\n      body: JSON.stringify({ email: address }),\n    })\n  } catch (_e) {\n    // The request never reached the server. That is a fact about the network and\n    // says nothing about the address, so it is the one case that reports itself.\n    if (error) error.hidden = false\n    return\n  }\n\n  // Completed — at ANY status, and without looking at what came back. See the\n  // module note: the response must not distinguish a known address from an\n  // unknown one, and the surest way to honour that is never to consult it.\n  if (sent) sent.hidden = false\n  for (const node of [email, form.querySelector('button[type=\"submit\"]')]) {\n    if (node) node.disabled = true\n  }\n}\n\n/** Attach both behaviours to one chrome `<section>`. */\nfunction enhanceAccountChrome(section, fetchImpl) {\n  try {\n    // Marks that script has taken over, which is what lets the form stop being an\n    // inline part of the page and become an overlay (see `styles.css`).\n    section.setAttribute('data-account-chrome-enhanced', '')\n    setDialog(section, false)\n\n    const openers = section.querySelectorAll(OPEN_SELECTOR)\n    for (let i = 0; i < openers.length; i++) {\n      openers[i].addEventListener('click', function () {\n        setDialog(section, true)\n      })\n    }\n    const closers = section.querySelectorAll(CLOSE_SELECTOR)\n    for (let i = 0; i < closers.length; i++) {\n      closers[i].addEventListener('click', function () {\n        setDialog(section, false)\n      })\n    }\n\n    const form = section.querySelector(DIALOG_SELECTOR)\n    if (form && typeof form.addEventListener === 'function') {\n      form.addEventListener('submit', function (event) {\n        if (typeof event.preventDefault === 'function') event.preventDefault()\n        void submitAddress(section, form, fetchImpl)\n      })\n    }\n  } catch (_e) {\n    // Isolation: enhancement failure leaves the native-post baseline.\n  }\n}\n\n/** Enhance every chrome in `root` (defaults to `document`). */\nfunction enhanceAllAccountChrome(root) {\n  const scope = root || (typeof document !== 'undefined' ? document : null)\n  if (!scope) return\n  const sections = scope.querySelectorAll(CHROME_SELECTOR)\n  for (let i = 0; i < sections.length; i++) enhanceAccountChrome(sections[i])\n}\n\n// Auto-init when shipped to the browser; inert under Node/JSDOM-less imports.\nif (typeof document !== 'undefined') {\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', function () {\n      enhanceAllAccountChrome()\n    })\n  } else {\n    enhanceAllAccountChrome()\n  }\n}\n}"
